import{z as p,x as A,o as t,c as C,q as r,j as l,D as i,d as o,s as n,S as E,b as a}from"./chunks/framework.C8m1ZpeB.js";const D=JSON.parse('{"title":"Cookie 与会话","description":"","frontmatter":{"title":"Cookie 与会话","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/cookies-sessions.md","filePath":"cs/cookies-sessions.md","lastUpdated":1791413859000}'),d={name:"cs/cookies-sessions.md"};function k(B,e,c,T,S,m){const s=A("Mermaid");return t(),C("div",null,[e[2]||(e[2]=r('<h1 id="cookie-与会话" tabindex="-1">Cookie 与会话 <a class="header-anchor" href="#cookie-与会话" aria-label="Permalink to &quot;Cookie 与会话&quot;">​</a></h1><div class="epigraph"><p>HTTP 无状态；Cookie 把小块状态交给用户代理回带，服务器才能认出「同一会话」。属性决定范围、寿命与是否只走 HTTPS。</p><footer>—— 据 RFC 6265 Cookies；RFC 9110 无状态对照整理</footer></div><p>主干 HTTP 已说无状态。<a href="/cs/http3">上一课</a> 不改语义。缺口是<strong>会话怎么挂上</strong>：Set-Cookie、作用域、Secure/HttpOnly/SameSite。本课不把内容协商写完。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>购物车、登录不能每请求重认证密码。Cookie：服务器 Set-Cookie，之后请求自动带 Cookie 头。域名与路径限制范围；Expires/Max-Age；Secure 限制 HTTPS；HttpOnly 挡脚本读；SameSite 减 CSRF。会话 ID 应是随机，服务器侧存会话——Cookie 里只放引用。持久连接复用时必须隔离不同用户，虚拟主机尤其。</p><p><span class="marginnote">直觉类比：Cookie 是服务器发的一张「游乐园手环」——乐园不记你的脸（HTTP 无状态），只认手环编号；每玩一个项目出示同一编号，后台查到你的档案。手环上只印编号不印档案，这正是「会话 ID 要随机、Cookie 只放引用」的意思。</span></p><p>不要把 Cookie 写成 JWT 课：可以是不透明 ID。</p><p><span class="marginnote">RFC 6265。第三方 Cookie 在浏览器政策下萎缩，本课钉协议对象。</span></p><h3 id="http-仍无状态" tabindex="-1">HTTP 仍无状态 <a class="header-anchor" href="#http-仍无状态" aria-label="Permalink to &quot;HTTP 仍无状态&quot;">​</a></h3><p>Cookie 外挂引用，服务器存会话。缓存必须 Vary。0-RTT 带 Cookie 有重放。IP 不能当身份。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>画：响应 Set-Cookie → 存储 → 后续请求带上。对照：服务端会话 vs 客户端存全部状态。与 QUIC 0-RTT：早数据带 Cookie 有重放，须绑定。</p>',12)),(t(),l(E,null,{default:i(()=>[n(s,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20SET%5B%22Set-Cookie%22%5D%20--%3E%20UA%5B%22%E7%94%A8%E6%88%B7%E4%BB%A3%E7%90%86%E5%AD%98%E5%82%A8%22%5D%0A%20%20UA%20--%3E%20REQ%5B%22%E4%B9%8B%E5%90%8E%E8%AF%B7%E6%B1%82%E5%B8%A6%E5%9B%9E%22%5D%0A%20%20SID%5B%22%E4%B8%8D%E9%80%8F%E6%98%8E%E4%BC%9A%E8%AF%9D%20ID%22%5D%20--%3E%20SRV%5B%22%E6%9C%8D%E5%8A%A1%E5%99%A8%E4%BC%9A%E8%AF%9D%E8%A1%A8%22%5D%0A"})]),fallback:i(()=>[...e[0]||(e[0]=[o(" Loading... ",-1)])]),_:1})),e[3]||(e[3]=a("h2",{id:"机制",tabindex:"-1"},[o("机制 "),a("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),e[4]||(e[4]=a("p",null,[o("CDN 缓存必须对 "),a("code",null,"Cookie"),o(" 与 "),a("code",null,"Set-Cookie"),o(" 正确 "),a("code",null,"Vary"),o("，否则串会话——后课 CDN 层次。H2/H3 多请求共享连接，Cookie 仍按请求头。NAT 后 IP 不能当身份。TLS 入口提供机密，Cookie 提供关联。")],-1)),e[5]||(e[5]=a("p",null,"安全：会话固定、CSRF、缺失 Secure 是边界，不写利用手册。",-1)),(t(),l(E,null,{default:i(()=>[n(s,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20LR%0A%20%20S1%5B%22%E6%98%8E%E6%96%87%E4%BF%A1%E9%81%93%E8%A2%AB%E7%AA%83%E5%90%AC%22%5D%20--%20%22Secure%3A%20%E5%8F%AA%E8%B5%B0%20HTTPS%22%20--%3E%20OK%5B%22%E4%BC%9A%E8%AF%9D%20ID%20%E4%B8%8D%E5%A4%96%E6%B3%84%22%5D%0A%20%20S2%5B%22XSS%20%E8%84%9A%E6%9C%AC%E8%AF%BB%20document.cookie%22%5D%20--%20%22HttpOnly%3A%20%E8%84%9A%E6%9C%AC%E8%AF%BB%E4%B8%8D%E5%88%B0%22%20--%3E%20OK%0A%20%20S3%5B%22%E7%AC%AC%E4%B8%89%E6%96%B9%E7%BD%91%E7%AB%99%E6%9B%BF%E4%BD%A0%E5%8F%91%E8%AF%B7%E6%B1%82%22%5D%20--%20%22SameSite%3A%20%E8%B7%A8%E7%AB%99%E4%B8%8D%E5%B8%A6%20Cookie%22%20--%3E%20OK%0A"})]),fallback:i(()=>[...e[1]||(e[1]=[o(" Loading... ",-1)])]),_:1})),e[6]||(e[6]=r('<p><span class="marginnote">常见误区：以为 Cookie 是「浏览器缓存」的一种。缓存省的是重复下载，Cookie 回带的是身份引用；两者都存在本地，用途却是两条线。CDN 若把带 Cookie 的响应当普通缓存存下发给别人，就会串会话——这才是本课反复提 Vary 的原因。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入浏览器存储 localStorage 的全部。内容协商与压缩是下一课。后课默认：会话 = Cookie 引用 + 服务器状态；HTTP 仍然无状态协议。</p><p>把整份用户档案放进 Cookie 会超大小且泄露。</p><p>下一课<a href="/cs/content-negotiation">内容协商与压缩</a>。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Cookie 在无状态 HTTP 上外挂会话。</li><li>属性约束范围、寿命与信道。</li><li>缓存与 0-RTT 要防串会话与重放。</li><li>后课只引用本课钉死的对象，不从该领域总问题重开。</li><li>出处：RFC 6265；RFC 9110。</li></ul><p><span class="marginnote">数字实例：单条 Cookie 约 4 KB、每域名几十条封顶，所以把整份用户档案塞进 Cookie 既超限又泄露。正确做法是只放一个 128 位随机会话 ID（32 个十六进制字符），真正的档案放在服务器的会话表或 Redis 里。</span></p>',8))])}const u=p(d,[["render",k]]);export{D as __pageData,u as default};
